/**
 * iRaceControl Race Report PDF parser.
 *
 * Reports are generated by iRaceControl (flattened single-stream text from unpdf).
 * Parsing uses section anchors, not line breaks.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { extractText, getDocumentProxy } from 'unpdf';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DEBUG_PREVIEW_LENGTH = 5000;
const PARSER_DEBUG_PREVIEW_LENGTH = 200;
const PARSER_DEBUG_REMAINING_TOKENS = 300;

const PARSER_DEBUG_FILES = {
  fullText: 'race-control-debug-full.txt',
  resultsSection: 'race-control-results-section.txt',
  tokens: 'race-control-results-tokens.json',
  anchors: 'race-control-result-anchors.json',
  rowAttempts: 'race-control-parsed-row-attempts.json',
  failure: 'race-control-parser-failure.json',
  failedRows: 'race-control-failed-rows.json',
};

function resolveParserDebugDir() {
  if (process.env.VERCEL) return '/tmp';
  return path.join(__dirname, '..', 'data');
}

function resolveParserDebugPath(filename) {
  return path.join(resolveParserDebugDir(), filename);
}

function writeParserDebugTextFile(filename, text) {
  const filePath = resolveParserDebugPath(filename);
  const dir = path.dirname(filePath);
  if (!process.env.VERCEL) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(filePath, String(text || ''), 'utf8');
  return filePath;
}

function writeParserDebugJsonFile(filename, payload) {
  const filePath = resolveParserDebugPath(filename);
  const dir = path.dirname(filePath);
  if (!process.env.VERCEL) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(filePath, `${JSON.stringify(payload, null, 2)}\n`, 'utf8');
  return filePath;
}

function charIndexToTokenIndex(sectionText, charIndex) {
  const prefix = sectionText.slice(0, Math.max(0, charIndex)).trim();
  if (!prefix) return 0;
  return prefix.split(/\s+/).filter(Boolean).length;
}

function buildSectionPreview(sectionText, charIndex, beforeChars = 120, afterChars = 120) {
  const start = Math.max(0, charIndex - beforeChars);
  const end = Math.min(sectionText.length, charIndex + afterChars);
  return sectionText.slice(start, end).trim();
}

function isIntervalToken(token) {
  const value = String(token || '');
  return isTimeToken(value) || /^\d+\.\d+$/.test(value);
}

function normalizeOptionalGap(value) {
  if (value == null || value === '-') return null;
  return value;
}

const MIN_RESULT_TAIL_TOKENS = 10;
const MIN_DNF_RESULT_TAIL_TOKENS = 7;

function isLapsPhraseTokenPair(tokens, startIndex) {
  return (
    startIndex + 1 < tokens.length &&
    /^\d+$/.test(String(tokens[startIndex])) &&
    String(tokens[startIndex + 1]).toLowerCase() === 'laps'
  );
}

function formatLapsPhrase(tokens, startIndex) {
  return `${tokens[startIndex]} ${tokens[startIndex + 1]}`;
}

function parseGapIntervalMiddle(middle) {
  if (!middle.length) {
    return { gap: null, interval: null };
  }

  let gap = null;
  let interval = null;
  let cursor = 0;

  if (isLapsPhraseTokenPair(middle, 0)) {
    gap = formatLapsPhrase(middle, 0);
    cursor = 2;
  } else {
    const first = normalizeOptionalGap(middle[0]);
    if (first != null) {
      gap = first;
      cursor = 1;
    } else if (middle[0] === '-') {
      cursor = 1;
    }
  }

  const rest = middle.slice(cursor);
  if (!rest.length) {
    return { gap, interval };
  }

  if (rest.length === 1) {
    const token = rest[0];
    if (isIntervalToken(token)) {
      interval = token;
    } else if (token !== '-') {
      interval = token;
    }
    return { gap, interval };
  }

  if (isLapsPhraseTokenPair(rest, 0)) {
    interval = formatLapsPhrase(rest, 0);
    return { gap, interval };
  }

  if (isIntervalToken(rest[0])) {
    interval = rest[0];
  }

  return { gap, interval };
}

function parseDnfLapsOnlySuffix(remaining) {
  if (!remaining.length) return null;

  const status = remaining[remaining.length - 1];
  if (!DNF_STATUS_VALUES.has(status)) return null;

  const middle = remaining.slice(0, -1);
  const { gap, interval } = parseGapIntervalMiddle(middle);

  return {
    gap,
    interval,
    bestLap: null,
    bestLapOn: null,
    status,
  };
}

function parseResultRowSuffix(remaining) {
  if (remaining.length < 3) return null;

  const status = remaining[remaining.length - 1];
  if (!STATUS_VALUES.has(status)) return null;

  const bestLapOnRaw = remaining[remaining.length - 2];
  let bestLapOn = null;
  if (bestLapOnRaw !== '-') {
    bestLapOn = Number(bestLapOnRaw);
    if (!Number.isFinite(bestLapOn)) return null;
  }

  const bestLapRaw = remaining[remaining.length - 3];
  if (bestLapRaw !== '-' && !isTimeToken(bestLapRaw)) return null;

  const { gap, interval } = parseGapIntervalMiddle(remaining.slice(0, -3));

  return {
    gap,
    interval,
    bestLap: bestLapRaw === '-' ? null : bestLapRaw,
    bestLapOn,
    status,
  };
}

function parseResultRowTail(tail) {
  if (!Array.isArray(tail) || tail.length < MIN_DNF_RESULT_TAIL_TOKENS) return null;

  let i = 0;
  const licenseClass = tail[i++];
  if (!LICENSE_CLASS_PATTERN.test(licenseClass)) return null;

  const safetyRating = Number(tail[i++]);
  const iRating = Number(tail[i++]);
  const grid = Number(tail[i++]);
  const incidents = Number(tail[i++]);
  const laps = Number(tail[i++]);
  if (
    !Number.isFinite(safetyRating) ||
    !Number.isFinite(iRating) ||
    !Number.isFinite(grid) ||
    !Number.isFinite(incidents) ||
    !Number.isFinite(laps)
  ) {
    return null;
  }

  const finishCandidate = tail[i];
  if (finishCandidate === '-' || isTimeToken(finishCandidate)) {
    i += 1;
    const suffix = parseResultRowSuffix(tail.slice(i));
    if (!suffix) return null;

    return {
      licenseClass,
      safetyRating,
      iRating,
      grid,
      incidents,
      laps,
      finishTime: finishCandidate === '-' ? null : finishCandidate,
      gap: suffix.gap,
      interval: suffix.interval,
      bestLap: suffix.bestLap,
      bestLapOn: suffix.bestLapOn,
      status: suffix.status,
    };
  }

  const dnfSuffix = parseDnfLapsOnlySuffix(tail.slice(i));
  if (!dnfSuffix) return null;

  return {
    licenseClass,
    safetyRating,
    iRating,
    grid,
    incidents,
    laps,
    finishTime: null,
    gap: dnfSuffix.gap,
    interval: dnfSuffix.interval,
    bestLap: dnfSuffix.bestLap,
    bestLapOn: dnfSuffix.bestLapOn,
    status: dnfSuffix.status,
  };
}

function diagnoseResultRowTailDetailed(tail) {
  const parserState = { tailTokenCount: tail?.length ?? 0 };

  if (!Array.isArray(tail) || tail.length < MIN_DNF_RESULT_TAIL_TOKENS) {
    return {
      reason: `Tail too short (${tail?.length ?? 0} tokens, need ${MIN_DNF_RESULT_TAIL_TOKENS}).`,
      field: 'tail',
      parserState,
    };
  }

  let i = 0;
  const licenseClass = tail[i++];
  parserState.licenseClass = licenseClass;
  if (!LICENSE_CLASS_PATTERN.test(licenseClass)) {
    return {
      reason: `Invalid license class (${licenseClass}).`,
      field: 'licenseClass',
      parserState,
    };
  }

  const safetyRating = Number(tail[i++]);
  const iRating = Number(tail[i++]);
  const grid = Number(tail[i++]);
  const incidents = Number(tail[i++]);
  const laps = Number(tail[i++]);
  parserState.safetyRating = tail[i - 5];
  parserState.iRating = tail[i - 4];
  parserState.grid = tail[i - 3];
  parserState.incidents = tail[i - 2];
  parserState.laps = tail[i - 1];

  if (
    !Number.isFinite(safetyRating) ||
    !Number.isFinite(iRating) ||
    !Number.isFinite(grid) ||
    !Number.isFinite(incidents) ||
    !Number.isFinite(laps)
  ) {
    return {
      reason: `Numeric tail invalid (SR=${parserState.safetyRating}, iR=${parserState.iRating}, grid=${parserState.grid}, inc=${parserState.incidents}, laps=${parserState.laps}).`,
      field: 'numericTail',
      parserState,
    };
  }

  const finishCandidate = tail[i];
  parserState.finishTime = finishCandidate;
  if (finishCandidate === '-' || isTimeToken(finishCandidate)) {
    const remaining = tail.slice(i + 1);
    parserState.remainingAfterFinishTime = remaining;

    if (remaining.length < 3) {
      return {
        reason: `Too few suffix tokens after finishTime (${remaining.length}, need at least 3).`,
        field: 'suffix',
        parserState,
      };
    }

    const status = remaining[remaining.length - 1];
    parserState.status = status;
    if (!STATUS_VALUES.has(status)) {
      return {
        reason: `Invalid status (${status}).`,
        field: 'status',
        parserState,
      };
    }

    const bestLapOnRaw = remaining[remaining.length - 2];
    parserState.bestLapOn = bestLapOnRaw;
    if (bestLapOnRaw !== '-' && !Number.isFinite(Number(bestLapOnRaw))) {
      return {
        reason: `Invalid bestLapOn (${bestLapOnRaw}).`,
        field: 'bestLapOn',
        parserState,
      };
    }

    const bestLapRaw = remaining[remaining.length - 3];
    parserState.bestLap = bestLapRaw;
    if (bestLapRaw !== '-' && !isTimeToken(bestLapRaw)) {
      return {
        reason: `Invalid bestLap (${bestLapRaw}).`,
        field: 'bestLap',
        parserState,
      };
    }

    parserState.gapIntervalMiddle = remaining.slice(0, -3);
  } else {
    parserState.remainingAfterFinishTime = tail.slice(i);
    const dnfSuffix = parseDnfLapsOnlySuffix(tail.slice(i));
    if (!dnfSuffix) {
      return {
        reason: `Invalid DNF suffix after laps (${tail.slice(i).join(' ')}).`,
        field: 'dnfSuffix',
        parserState,
      };
    }
    parserState.status = dnfSuffix.status;
    parserState.gapIntervalMiddle = tail.slice(i, -1);
  }

  const parsed = parseResultRowTail(tail);
  if (parsed) return null;

  return {
    reason: `Gap/interval suffix invalid (${(parserState.gapIntervalMiddle || []).join(' ')}).`,
    field: 'gapInterval',
    parserState,
  };
}

function tryParseResultRowIdentityAndTail(tokens, identityStart, maxIdentityLen) {
  let best = null;

  for (let identityLen = 3; identityLen <= maxIdentityLen; identityLen += 1) {
    const identityTokens = tokens.slice(identityStart, identityStart + identityLen);
    const identity = parseDriverIdentity(identityTokens);
    if (!identity) continue;

    const tail = tokens.slice(identityStart + identityLen);
    if (!tail.length || !LICENSE_CLASS_PATTERN.test(tail[0])) continue;

    const tailParsed = parseResultRowTail(tail);
    if (!tailParsed) continue;

    if (!best || identityLen < best.identityLen) {
      best = { identity, tail, tailParsed, identityLen };
    }
  }

  return best;
}

function diagnoseParseOneResultRowDetailed(tokens, startIdx) {
  const rowText = tokens.join(' ');
  const parserState = {
    tokenCount: tokens.length,
    startIdx,
  };

  if (startIdx + 14 >= tokens.length) {
    return {
      reason: `Insufficient tokens (${tokens.length}) for a result row starting at index ${startIdx}.`,
      field: 'tokens',
      parserState,
      rowText,
      tokens,
    };
  }

  if (
    !/^\d+$/.test(tokens[startIdx]) ||
    !/^\d+$/.test(tokens[startIdx + 1]) ||
    !/^\d+$/.test(tokens[startIdx + 2])
  ) {
    return {
      reason: `Row prefix is not position/classPosition/carNumber (${tokens.slice(startIdx, startIdx + 5).join(' ')}).`,
      field: 'rowPrefix',
      parserState,
      rowText,
      tokens,
    };
  }

  const position = Number(tokens[startIdx]);
  const identityStart = startIdx + 3;
  const maxIdentityLen = tokens.length - startIdx - 3 - MIN_DNF_RESULT_TAIL_TOKENS;
  parserState.position = position;
  parserState.classPosition = Number(tokens[startIdx + 1]);
  parserState.carNumber = Number(tokens[startIdx + 2]);

  if (maxIdentityLen < 1) {
    return {
      reason: `Not enough tokens after car number for identity + tail (tokens=${tokens.length}).`,
      field: 'identitySplit',
      parserState,
      rowText,
      tokens,
    };
  }

  let bestFailure = null;

  for (let identityLen = 3; identityLen <= maxIdentityLen; identityLen += 1) {
    const identityTokens = tokens.slice(identityStart, identityStart + identityLen);
    const identity = parseDriverIdentity(identityTokens);
    parserState.identityLen = identityLen;
    parserState.identityTokens = identityTokens;

    if (!identity) {
      bestFailure = {
        reason: `Driver identity not resolved for identityLen=${identityLen}.`,
        field: 'driverIdentity',
        parserState: {
          ...parserState,
          identityAttempt: identityTokens.join(' '),
        },
        rowText,
        tokens,
      };
      continue;
    }

    const tail = tokens.slice(identityStart + identityLen);
    if (!tail.length || !LICENSE_CLASS_PATTERN.test(tail[0])) {
      bestFailure = {
        reason: `${identity.driverName}: tail does not start with license class (${tail[0] ?? 'missing'}).`,
        field: 'licenseClass',
        parserState: {
          ...parserState,
          driverName: identity.driverName,
          tailTokens: tail,
        },
        rowText,
        tokens,
      };
      continue;
    }

    parserState.driverName = identity.driverName;
    parserState.nationality = identity.nationality;
    parserState.car = identity.car;

    parserState.tailTokens = tail;
    const tailFailure = diagnoseResultRowTailDetailed(tail);
    if (tailFailure) {
      bestFailure = {
        reason: `${identity.driverName}: ${tailFailure.reason}`,
        field: tailFailure.field,
        parserState: {
          ...parserState,
          ...tailFailure.parserState,
        },
        rowText,
        tokens,
      };
      continue;
    }

    return null;
  }

  return (
    bestFailure || {
      reason: `Could not split driver identity from result tail after token index ${identityStart}.`,
      field: 'identitySplit',
      parserState,
      rowText,
      tokens,
    }
  );
}

function diagnoseResultRowTailFailure(tail) {
  const detailed = diagnoseResultRowTailDetailed(tail);
  return detailed?.reason ?? null;
}

function sliceResultRowText(sectionText, candidate, candidates) {
  const nextPositionIndex = candidates.find(
    (item) => item.index > candidate.index && item.position === candidate.position + 1
  )?.index;
  const endIndex = nextPositionIndex ?? sectionText.length;
  return sectionText.slice(candidate.index, endIndex).trim();
}

function collectFailedRowDiagnostics(sectionText, candidates = null) {
  const section = String(sectionText || '');
  const anchorCandidates = candidates || findResultRowCandidates(section);
  const failedRows = [];
  const successfulPositions = [];

  const seenPositions = new Set();
  for (const candidate of anchorCandidates) {
    if (seenPositions.has(candidate.position)) continue;
    seenPositions.add(candidate.position);

    const rowText = sliceResultRowText(section, candidate, anchorCandidates);
    const tokens = rowText.split(/\s+/).filter(Boolean);
    const parsed = parseOneResultRow(tokens, 0);

    if (parsed?.result?.position === candidate.position) {
      successfulPositions.push(candidate.position);
      continue;
    }

    const detail = diagnoseParseOneResultRowDetailed(tokens, 0);
    failedRows.push({
      position: candidate.position,
      reason: detail?.reason || 'parseOneResultRow returned null',
      rowText,
      tokens,
      field: detail?.field || 'unknown',
      parserState: detail?.parserState || {},
    });
  }

  failedRows.sort((a, b) => a.position - b.position);
  successfulPositions.sort((a, b) => a - b);

  return {
    failedRows,
    failedRowCount: failedRows.length,
    failedPositions: failedRows.map((row) => row.position),
    successfulPositions,
  };
}

function writeFailedRowDiagnostics(sectionText, candidates = null) {
  const diagnostics = collectFailedRowDiagnostics(sectionText, candidates);
  let failedRowsPath = null;

  if (diagnostics.failedRowCount > 0) {
    failedRowsPath = writeParserDebugJsonFile(PARSER_DEBUG_FILES.failedRows, {
      failedRows: diagnostics.failedRows,
    });
  } else {
    const failedRowsFilePath = resolveParserDebugPath(PARSER_DEBUG_FILES.failedRows);
    try {
      if (fs.existsSync(failedRowsFilePath)) fs.unlinkSync(failedRowsFilePath);
    } catch {
      // ignore cleanup errors
    }
  }

  return {
    ...diagnostics,
    failedRowsPath,
  };
}

function diagnoseParseOneResultRowFailure(tokens, startIdx) {
  const detailed = diagnoseParseOneResultRowDetailed(tokens, startIdx);
  return detailed?.reason ?? null;
}

function buildResultsParseInstrumentation(sectionText) {
  const section = String(sectionText || '');
  const tokens = section.trim() ? section.trim().split(/\s+/).filter(Boolean) : [];
  const tokensPayload = { tokenCount: tokens.length, tokens };
  const tokensPath = writeParserDebugJsonFile(PARSER_DEBUG_FILES.tokens, tokensPayload);

  const candidates = findResultRowCandidates(section);
  const anchors = candidates.map((candidate) => ({
    position: candidate.position,
    classPosition: candidate.classPosition,
    carNumber: String(candidate.carNumber),
    charIndex: candidate.index,
    tokenIndex: charIndexToTokenIndex(section, candidate.index),
    preview: section.slice(candidate.index, candidate.index + PARSER_DEBUG_PREVIEW_LENGTH).trim(),
  }));
  const anchorsPath = writeParserDebugJsonFile(PARSER_DEBUG_FILES.anchors, {
    anchorCount: anchors.length,
    anchors,
  });

  const attempts = [];
  let failure = null;
  let searchFrom = 0;
  let lastSuccessfulPosition = 0;
  let lastSuccessfulCharIndex = null;

  for (let expectedPosition = 1; expectedPosition <= 60; expectedPosition += 1) {
    const options = candidates.filter(
      (candidate) =>
        candidate.index >= searchFrom && candidate.position === expectedPosition
    );

    if (!options.length) {
      failure = {
        failedAtPosition: expectedPosition,
        reason: `No row anchor found for position ${expectedPosition} at or after char index ${searchFrom}.`,
        lastSuccessfulPosition: lastSuccessfulPosition || null,
        remainingTokens: tokens.slice(charIndexToTokenIndex(section, searchFrom)).slice(0, PARSER_DEBUG_REMAINING_TOKENS),
        sectionPreviewBeforeFailure: buildSectionPreview(section, searchFrom, 160, 0),
        sectionPreviewAfterFailure: buildSectionPreview(section, searchFrom, 0, 160),
      };
      break;
    }

    let accepted = null;
    for (const candidate of options) {
      const nextPositionIndex = candidates.find(
        (item) => item.index > candidate.index && item.position === expectedPosition + 1
      )?.index;
      const endIndex = nextPositionIndex ?? section.length;
      const rowText = section.slice(candidate.index, endIndex).trim();
      const rowTokens = rowText.split(/\s+/).filter(Boolean);
      const parsed = parseOneResultRow(rowTokens, 0);
      const preview = rowText.slice(0, PARSER_DEBUG_PREVIEW_LENGTH);

      if (parsed?.result?.position === expectedPosition) {
        attempts.push({
          position: expectedPosition,
          success: true,
          driverName: parsed.result.driverName,
          carNumber: String(parsed.result.carNumber),
          charIndex: candidate.index,
          tokenIndex: charIndexToTokenIndex(section, candidate.index),
          preview,
        });
        accepted = { ...candidate, endIndex };
        break;
      }

      attempts.push({
        position: expectedPosition,
        success: false,
        reason: diagnoseParseOneResultRowFailure(rowTokens, 0) || 'parseOneResultRow returned null',
        charIndex: candidate.index,
        tokenIndex: charIndexToTokenIndex(section, candidate.index),
        preview,
      });
    }

    if (!accepted) {
      const failedAttempt = attempts[attempts.length - 1];
      failure = {
        failedAtPosition: expectedPosition,
        reason:
          failedAttempt?.reason ||
          `Sequential row validation failed for position ${expectedPosition}.`,
        lastSuccessfulPosition: lastSuccessfulPosition || null,
        remainingTokens: tokens
          .slice(failedAttempt?.tokenIndex ?? charIndexToTokenIndex(section, searchFrom))
          .slice(0, PARSER_DEBUG_REMAINING_TOKENS),
        sectionPreviewBeforeFailure: buildSectionPreview(
          section,
          failedAttempt?.charIndex ?? searchFrom,
          160,
          0
        ),
        sectionPreviewAfterFailure: buildSectionPreview(
          section,
          failedAttempt?.charIndex ?? searchFrom,
          0,
          160
        ),
      };
      break;
    }

    lastSuccessfulPosition = expectedPosition;
    lastSuccessfulCharIndex = accepted.index;
    searchFrom = accepted.index + 1;
  }

  const attemptsPath = writeParserDebugJsonFile(PARSER_DEBUG_FILES.rowAttempts, {
    attemptCount: attempts.length,
    attempts,
  });

  let failurePath = null;
  const hasFailedAttempt = attempts.some((attempt) => !attempt.success);
  const stoppedBefore35 =
    failure &&
    failure.failedAtPosition <= 35 &&
    lastSuccessfulPosition < 35;
  const failureFilePath = resolveParserDebugPath(PARSER_DEBUG_FILES.failure);
  if (failure && (hasFailedAttempt || stoppedBefore35)) {
    failurePath = writeParserDebugJsonFile(PARSER_DEBUG_FILES.failure, failure);
  } else {
    try {
      if (fs.existsSync(failureFilePath)) fs.unlinkSync(failureFilePath);
    } catch {
      // ignore cleanup errors
    }
  }

  const positionAnchorsDetected = [
    ...new Set(anchors.map((anchor) => anchor.position)),
  ].sort((a, b) => a - b);
  const positions1Through35Detected = positionAnchorsDetected.filter(
    (position) => position >= 1 && position <= 35
  );

  return {
    tokensPath,
    anchorsPath,
    attemptsPath,
    failurePath,
    tokenCount: tokens.length,
    anchorCount: anchors.length,
    parsedAttemptCount: attempts.length,
    failedAtPosition:
      hasFailedAttempt || stoppedBefore35 ? failure?.failedAtPosition ?? null : null,
    failureReason:
      hasFailedAttempt || stoppedBefore35 ? failure?.reason ?? null : null,
    lastSuccessfulPosition: lastSuccessfulPosition || null,
    sequentialAnchorsAccepted: attempts.filter((attempt) => attempt.success).length,
    positionAnchorsDetected,
    positions1Through35Detected,
    positions1Through35Count: positions1Through35Detected.length,
    allPositions1Through35AnchorsDetected: positions1Through35Detected.length === 35,
  };
}

function writeResultsParseInstrumentation(sectionText) {
  const section = String(sectionText || '');
  const resultsSectionPath = writeParserDebugTextFile(
    PARSER_DEBUG_FILES.resultsSection,
    section
  );
  const instrumentation = buildResultsParseInstrumentation(section);

  return {
    debugFilesWritten: true,
    resultsSectionPath,
    resultsSectionLength: section.length,
    ...instrumentation,
  };
}

