const STATUS_VALUES = new Set(['Running', 'Disco', 'DQ', 'DNQ', 'Disqualified']);
const DNF_STATUS_VALUES = new Set(['Disco', 'DQ', 'DNQ', 'Disqualified']);
const LICENSE_CLASS_PATTERN = /^[A-Z]{1,3}$/;

const TIME_TOKEN =
  /^(\d{1,2}:\d{2}:\d{2}\.\d{3}|\d{1,2}:\d{2}\.\d{3}|-)$/;

const RESULT_ROW_START_PATTERN = /\b(\d{1,2}) (\d{1,2}) (\d{1,3}) ([A-Z])/g;

function resolveDebugFilePath() {
  if (process.env.VERCEL) return '/tmp/race-control-debug.txt';
  return path.join(__dirname, '..', 'data', 'race-control-debug.txt');
}

function writeExtractionDebugFile(text) {
  const filePath = resolveDebugFilePath();
  const dir = path.dirname(filePath);
  if (!process.env.VERCEL) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(filePath, String(text || ''), 'utf8');
  return filePath;
}

function detectStructuredResultRows(text) {
  return /\b\d+\s+\d+\s+\d+\s+[A-Za-z].+?\s+(?:Running|Disqualified|Disco|DQ|DNQ)\b/.test(
    String(text || '')
  );
}

function buildExtractionDebug(text, pageCount) {
  const raw = String(text || '');
  const trimmed = raw.trim();
  const extractedCharacterCount = raw.length;
  const pageTotal = Number(pageCount) || 0;
  const lineCount = trimmed ? trimmed.split(/\r?\n/).length : 0;
  const wordCount = trimmed ? trimmed.split(/\s+/).filter(Boolean).length : 0;
  const avgLineLength = lineCount > 0 ? extractedCharacterCount / lineCount : extractedCharacterCount;
  const charsPerPage = pageTotal > 0 ? extractedCharacterCount / pageTotal : extractedCharacterCount;

  const hasUsableText =
    extractedCharacterCount >= 100 && /[a-zA-Z]{3,}/.test(trimmed);

  const hasTableHeaders = /\b(Pos|Cls|Car|Driver|SOF|SESSION REPORTS)\b/i.test(trimmed);
  const hasStructuredRows = detectStructuredResultRows(trimmed);
  const tablesLikelyFlattened =
    hasTableHeaders && extractedCharacterCount > 200 && (lineCount <= 3 || !hasStructuredRows);

  const positionedTextLikely =
    extractedCharacterCount > 500 &&
    lineCount <= Math.max(3, pageTotal * 2) &&
    avgLineLength > 200;

  const ocrLikelyRequired =
    pageTotal > 0 ? charsPerPage < 80 && !hasUsableText : extractedCharacterCount === 0;

  let extractionMethod = 'plain text';
  if (ocrLikelyRequired) {
    extractionMethod = 'OCR required';
  }

  const extractionWarnings = [];
  if (extractedCharacterCount === 0) {
    extractionWarnings.push('PDF contained no extractable text.');
  } else if (extractedCharacterCount < 100) {
    extractionWarnings.push(
      `PDF contains only ${extractedCharacterCount} extracted characters.`
    );
  }
  if (tablesLikelyFlattened) {
    extractionWarnings.push('Tables may appear flattened in extracted text.');
  }
  if (positionedTextLikely) {
    extractionWarnings.push('PDF may contain positioned text.');
  }
  if (ocrLikelyRequired) {
    extractionWarnings.push('OCR may be required.');
  }

  return {
    debugTextPreview: raw.slice(0, DEBUG_PREVIEW_LENGTH),
    debug: {
      extractedCharacterCount,
      extractionMethod,
      pageCount: pageTotal,
      hasUsableText,
      lineCount,
      wordCount,
      tablesLikelyFlattened,
      positionedTextLikely,
      ocrLikelyRequired,
      debugFilePath: resolveDebugFilePath(),
      debugFileWritten: false,
    },
    extractionWarnings,
  };
}

function appendUniqueWarnings(target, warnings) {
  for (const warning of warnings || []) {
    if (!target.includes(warning)) target.push(warning);
  }
}

export function normalizeWhitespace(text) {
  return String(text || '').replace(/\s+/g, ' ').trim();
}

function isTimeToken(token) {
  return TIME_TOKEN.test(String(token || ''));
}

function compareTimes(a, b) {
  const toMs = (value) => {
    const parts = String(value).split(':');
    if (parts.length === 3) {
      return (
        Number(parts[0]) * 3600000 +
        Number(parts[1]) * 60000 +
        Number(parts[2]) * 1000
      );
    }
    if (parts.length === 2) {
      return Number(parts[0]) * 60000 + Number(parts[1]) * 1000;
    }
    return Number.MAX_SAFE_INTEGER;
  };
  return toMs(a) - toMs(b);
}

function extractNationality(tokens) {
  const sorted = [...NATIONALITY_PHRASES].sort(
    (a, b) => b.split(' ').length - a.split(' ').length
  );
  for (const phrase of sorted) {
    const parts = phrase.split(' ');
    if (tokens.length < parts.length + 1) continue;
    const tail = tokens.slice(-parts.length).join(' ');
    if (tail === phrase) {
      return { name: phrase, count: parts.length };
    }
  }
  if (tokens.length >= 2) {
    return { name: tokens[tokens.length - 1], count: 1 };
  }
  return null;
}

function parseDriverIdentityStrict(tokens) {
  if (!tokens.length) return null;

  for (const car of KNOWN_CARS) {
    const carParts = car.split(' ');
    for (let carIdx = 0; carIdx <= tokens.length - carParts.length; carIdx += 1) {
      const slice = tokens.slice(carIdx, carIdx + carParts.length).join(' ');
      if (slice !== car) continue;

      const beforeCar = tokens.slice(0, carIdx);
      const nationality = extractNationality(beforeCar);
      if (!nationality) continue;

      const driverTokens = beforeCar.slice(0, beforeCar.length - nationality.count);
      const driverName = driverTokens.join(' ').trim();
      if (!driverName || driverName.length < 2) continue;

      return {
        driverName,
        nationality: nationality.name,
        car,
      };
    }
  }

  return null;
}

function parseDriverIdentityLenient(tokens) {
  if (tokens.length < 3) return null;

  for (const natCount of [2, 1]) {
    if (tokens.length <= natCount + 1) continue;
    const nationality = tokens.slice(-natCount).join(' ');
    const beforeNat = tokens.slice(0, -natCount);

    for (let carLen = Math.min(4, beforeNat.length - 1); carLen >= 1; carLen -= 1) {
      const car = beforeNat.slice(-carLen).join(' ');
      const driverName = beforeNat.slice(0, -carLen).join(' ').trim();
      if (driverName.length < 2 || !/[A-Za-z]/.test(driverName)) continue;
      return { driverName, nationality, car };
    }
  }

  return null;
}

function parseDriverIdentity(tokens) {
  return parseDriverIdentityStrict(tokens) || parseDriverIdentityLenient(tokens);
}

export function parseRaceHeader(text) {
  const warnings = [];
  const normalized = normalizeWhitespace(text);

  const match = normalized.match(
    /This document was generated:\s*(\d{2}\/\d{2}\/\d{4}\s+\d{2}:\d{2}:\d{2})\s+RACE\s*-\s*(.*?)\s*-\s*\([^)]*\)\s*-\s*(\d+)\s+SOF/i
  );

  if (match) {
    return {
      generatedAt: match[1].trim(),
      trackName: match[2].trim(),
      sof: Number(match[3]),
      warnings,
    };
  }

  const generatedMatch = normalized.match(
    /This document was generated:\s*([\d/:\s]+?)\s+RACE\s*-\s*(.*?)\s*-\s*\([^)]*\)/i
  );
  const sofMatch = normalized.match(/\b(\d{3,5})\s+SOF\b/i);

  if (generatedMatch) {
    if (sofMatch == null) warnings.push('SOF not detected in race header.');
    return {
      generatedAt: generatedMatch[1].trim(),
      trackName: generatedMatch[2].trim(),
      sof: sofMatch ? Number(sofMatch[1]) : null,
      warnings,
    };
  }

  warnings.push('Race header not detected.');
  return {
    generatedAt: null,
    trackName: null,
    sof: null,
    warnings,
  };
}

function extractRaceSummaryMeta(text, results) {
  const meta = {};
  const cautionLaps = text.match(/\bCaution Laps[:\s]+(\d+)/i);
  const leadChanges = text.match(/\bLead Changes[:\s]+(\d+)/i);
  const averageLapTime = text.match(/\bAverage Lap Time[:\s]+([\d:.]+)/i);
  const lapsCompletedHeader = text.match(/\bLaps Completed[:\s]+(\d+)/i);

  if (cautionLaps) meta.cautionLaps = Number(cautionLaps[1]);
  if (leadChanges) meta.leadChanges = Number(leadChanges[1]);
  if (averageLapTime) meta.averageLapTime = averageLapTime[1];
  if (lapsCompletedHeader) {
    meta.lapsCompleted = Number(lapsCompletedHeader[1]);
  } else if (results?.length) {
    meta.lapsCompleted = results[0]?.laps ?? null;
  }

  return meta;
}

function findResultRowCandidates(sectionText) {
  const candidates = [];
  const pattern = new RegExp(RESULT_ROW_START_PATTERN.source, 'g');
  let match;
  while ((match = pattern.exec(sectionText)) !== null) {
    candidates.push({
      index: match.index,
      position: Number(match[1]),
      classPosition: Number(match[2]),
      carNumber: Number(match[3]),
    });
  }
  return candidates;
}

function findSequentialResultRowStarts(sectionText) {
  const candidates = findResultRowCandidates(sectionText);
  const starts = [];
  let searchFrom = 0;

  for (let expectedPosition = 1; expectedPosition <= 60; expectedPosition += 1) {
    const options = candidates.filter(
      (candidate) =>
        candidate.index >= searchFrom && candidate.position === expectedPosition
    );

    let accepted = null;
    for (const candidate of options) {
      const nextPositionIndex = candidates.find(
        (item) => item.index > candidate.index && item.position === expectedPosition + 1
      )?.index;
      const endIndex = nextPositionIndex ?? sectionText.length;
      const rowText = sectionText.slice(candidate.index, endIndex).trim();
      const parsed = parseOneResultRow(rowText.split(/\s+/), 0);
      if (parsed?.result?.position === expectedPosition) {
        accepted = { ...candidate, endIndex };
        break;
      }
    }

    if (!accepted) break;
    starts.push(accepted);
    searchFrom = accepted.index + 1;
  }

  return starts;
}

export function getResultsSectionText(text) {
  const warnings = [];
  const lapChartIdx = text.indexOf('LAP CHART - RACE');
  if (lapChartIdx === -1) {
    warnings.push('LAP CHART - RACE anchor not found.');
    return { section: '', warnings };
  }

  const beforeLapChart = text.slice(0, lapChartIdx);
  const headerMatch = beforeLapChart.match(/\bPos\s+Cls\s+Car\s+Driver\b/i);
  if (headerMatch) {
    const afterHeader = beforeLapChart.slice(headerMatch.index + headerMatch[0].length);
    const rowStart = afterHeader.search(/\b\d+\s+\d+\s+\d+\s+[A-Z]/);
    if (rowStart !== -1) {
      return { section: afterHeader.slice(rowStart).trim(), warnings };
    }
  }

  const rowStart = beforeLapChart.search(/\b\d+\s+\d+\s+\d+\s+[A-Z][a-z]/);
  if (rowStart === -1) {
    warnings.push('No finishing results rows detected.');
    return { section: '', warnings };
  }

  return { section: beforeLapChart.slice(rowStart).trim(), warnings };
}

function parseOneResultRow(tokens, startIdx) {
  if (startIdx + 14 >= tokens.length) return null;
  if (
    !/^\d+$/.test(tokens[startIdx]) ||
    !/^\d+$/.test(tokens[startIdx + 1]) ||
    !/^\d+$/.test(tokens[startIdx + 2])
  ) {
    return null;
  }

  const position = Number(tokens[startIdx]);
  const classPosition = Number(tokens[startIdx + 1]);
  const carNumber = Number(tokens[startIdx + 2]);
  const identityStart = startIdx + 3;
  const maxIdentityLen = tokens.length - startIdx - 3 - MIN_DNF_RESULT_TAIL_TOKENS;

  if (maxIdentityLen < 1) return null;

  const parsedIdentity = tryParseResultRowIdentityAndTail(tokens, identityStart, maxIdentityLen);
  if (!parsedIdentity) return null;

  const { identity, tail, tailParsed, identityLen } = parsedIdentity;

  return {
    result: {
      position,
      classPosition,
      carNumber,
      driverName: identity.driverName,
      nationality: identity.nationality,
      car: identity.car,
      licenseClass: tailParsed.licenseClass,
      safetyRating: tailParsed.safetyRating,
      iRating: tailParsed.iRating,
      grid: tailParsed.grid,
      incidents: tailParsed.incidents,
      laps: tailParsed.laps,
      finishTime: tailParsed.finishTime,
      gap: tailParsed.gap,
      interval: tailParsed.interval,
      bestLap: tailParsed.bestLap,
      bestLapOn: tailParsed.bestLapOn,
      status: tailParsed.status,
      startPosition: tailParsed.grid,
      incidentCount: tailParsed.incidents,
      lapsCompleted: tailParsed.laps,
    },
    nextIdx: identityStart + identityLen + tail.length,
  };
}

export function parseResults(sectionText) {
  const warnings = [];
  const results = [];

  if (!sectionText?.trim()) {
    warnings.push('Results section is empty.');
    return {
      results,
      warnings,
      rowStarts: [],
      failedRowDiagnostics: collectFailedRowDiagnostics(''),
    };
  }

  const candidates = findResultRowCandidates(sectionText);
  const failedRowDiagnostics = collectFailedRowDiagnostics(sectionText, candidates);
  const rowStarts = findSequentialResultRowStarts(sectionText);
  const seenPositions = new Set();

  for (const candidate of candidates) {
    if (seenPositions.has(candidate.position)) continue;
    seenPositions.add(candidate.position);

    const rowText = sliceResultRowText(sectionText, candidate, candidates);
    const parsed = parseOneResultRow(rowText.split(/\s+/), 0);
    if (parsed?.result?.position === candidate.position) {
      results.push(parsed.result);
    }
  }

  if (!results.length) {
    warnings.push('No finishing results table detected in PDF text.');
  } else if (seenPositions.size > results.length) {
    warnings.push(
      `Detected ${seenPositions.size} result row anchors but parsed ${results.length} rows.`
    );
  } else if (failedRowDiagnostics.failedRowCount > 0) {
    warnings.push(
      `${failedRowDiagnostics.failedRowCount} anchored result row(s) failed validation (positions: ${failedRowDiagnostics.failedPositions.join(', ')}).`
    );
  }

  results.sort((a, b) => a.position - b.position);
  return { results, warnings, rowStarts, failedRowDiagnostics };
}

function classifySessionEventType(text) {
  const upper = String(text || '').toUpperCase();
  if (upper.includes('FULL COURSE YELLOW')) return 'full_course_yellow';
  if (upper.includes('GREEN FLAG')) return 'green_flag';
  if (upper.includes('ONE LAP TO GREEN')) return 'one_lap_to_green';
  if (upper.includes('PENALTIES CLEARED')) return 'penalties_cleared';
  if (upper.includes('RACE CONTROL')) return 'race_control';
  return 'other';
}

export function parseSessionReports(text) {
  const warnings = [];
  const startIdx = text.indexOf('SESSION REPORTS');
  const endIdx = text.indexOf('INCIDENT REPORTS');

  if (startIdx === -1) {
    warnings.push('SESSION REPORTS section not found.');
    return { raceEvents: [], warnings };
  }

  const section =
    endIdx === -1
      ? text.slice(startIdx + 'SESSION REPORTS'.length)
      : text.slice(startIdx + 'SESSION REPORTS'.length, endIdx);

  const raceEvents = [];
  const eventPattern =
    /(\d{2}:\d{2}:\d{2})\s+L(\d+)\s+(.+?)(?=\d{2}:\d{2}:\d{2}\s+L\d+\s|$)/gi;

  let match;
  while ((match = eventPattern.exec(section)) !== null) {
    const eventText = `${match[1]} L${match[2]} ${match[3].trim()}`;
    raceEvents.push({
      time: match[1],
      lap: Number(match[2]),
      text: eventText,
      type: classifySessionEventType(match[3]),
    });
  }

  if (!raceEvents.length) {
    warnings.push('No session report race events detected.');
  }

  return { raceEvents, warnings };
}

const INCIDENT_EVENT_PATTERN =
  /\b(\d+x(?:->\d+x)?|Meatball flag|Black flag|INVESTIGATING|Cleared black flag)\b/i;

function normalizeDriverKey(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function findMatchingResultRow(results = [], carNumber, driverName) {
  const byCar = results.find((row) => String(row.carNumber) === String(carNumber));
  if (byCar) return byCar;

  const targetName = normalizeDriverKey(driverName);
  return results.find((row) => normalizeDriverKey(row.driverName) === targetName) || null;
}

function extractEventsBlock(body) {
  const match = body.match(/EVENTS\s+([\s\S]*?)\s+LAPS\s/i);
  return match?.[1]?.trim() || '';
}

function extractRaceSection(block, label) {
  if (!block) return '';
  const pattern = new RegExp(`\\b${label}\\b`, 'i');
  const match = block.match(pattern);
  if (!match) return '';

  const start = match.index + match[0].length;
  const remainder = block.slice(start);
  const nextSection = remainder.search(/\b(PRACTICE|QUALIFY|RACE)\b/i);
  return (nextSection >= 0 ? remainder.slice(0, nextSection) : remainder).trim();
}

function parseRacePitStops(raceEventsText) {
  const pitStops = [];
  const pattern =
    /(\d{2}:\d{2}:\d{2})\s+L(-?\d+)\s+PIT STOP TIME:\s*([\d.]+)/gi;

  let match;
  while ((match = pattern.exec(raceEventsText)) !== null) {
    pitStops.push({
      time: match[1],
      lap: Number(match[2]),
      seconds: Number(match[3]),
    });
  }

  return pitStops;
}

function parseRaceIncidentEvents(raceEventsText) {
  const incidentEvents = [];
  const pattern = /(\d{2}:\d{2}:\d{2})\s+L(-?\d+)\s+([^]+?)(?=\d{2}:\d{2}:\d{2}\s+L|$)/gi;

  let match;
  while ((match = pattern.exec(raceEventsText)) !== null) {
    const text = match[3].trim();
    if (!INCIDENT_EVENT_PATTERN.test(text) && !/\b\d+x\b/i.test(text)) continue;
    incidentEvents.push({
      time: match[1],
      lap: Number(match[2]),
      text: `${match[1]} L${match[2]} ${text}`.trim(),
    });
  }

  return incidentEvents;
}

function parseRaceBestLapEvents(raceEventsText) {
  const bestLaps = [];
  const pattern =
    /(\d{2}:\d{2}:\d{2})\s+L(-?\d+)\s+New (personal|overall) best:\s*([\d:.]+)/gi;

  let match;
  while ((match = pattern.exec(raceEventsText)) !== null) {
    bestLaps.push({
      time: match[1],
      lap: Number(match[2]),
      type: match[3].toLowerCase(),
      lapTime: match[4],
    });
  }

  return bestLaps;
}

function parseLapTableBest(lapTableText) {
  let fastest = null;
  const pattern = /\b(\d+)\s+([\d:*.]+)(?:\s|$)/g;

  let match;
  while ((match = pattern.exec(lapTableText)) !== null) {
    const lapTime = match[2];
    if (lapTime === '*' || !isTimeToken(lapTime)) continue;
    if (!fastest || compareTimes(lapTime, fastest) < 0) {
      fastest = lapTime;
    }
  }

  return fastest;
}

function selectDriverBestLap({ resultRow, bestLapEvents, lapTableBest }) {
  if (resultRow?.bestLap && isTimeToken(resultRow.bestLap) && resultRow.bestLap !== '-') {
    return { bestLap: resultRow.bestLap, bestLapSource: 'results' };
  }

  let eventBest = null;
  for (const entry of bestLapEvents) {
    if (!entry.lapTime || !isTimeToken(entry.lapTime)) continue;
    if (!eventBest || compareTimes(entry.lapTime, eventBest.lapTime) < 0) {
      eventBest = entry;
    }
  }
  if (eventBest) {
    return { bestLap: eventBest.lapTime, bestLapSource: 'driverEvents' };
  }

  if (lapTableBest) {
    return { bestLap: lapTableBest, bestLapSource: 'lapTable' };
  }

  return { bestLap: null, bestLapSource: null };
}

function summarizePitStops(pitStops) {
  const numericStops = pitStops.filter((stop) => Number.isFinite(stop.seconds));
  const fastestPitStop = numericStops.length
    ? Math.min(...numericStops.map((stop) => stop.seconds))
    : null;
  const totalPitStopTime = numericStops.length
    ? numericStops.reduce((sum, stop) => sum + stop.seconds, 0)
    : null;

  return {
    pitStopCount: pitStops.length,
    fastestPitStop,
    totalPitStopTime,
  };
}

export function parseDriverReports(text, options = {}) {
  const warnings = [];
  const results = Array.isArray(options.results) ? options.results : [];
  const startIdx = text.indexOf('INCIDENT REPORTS');

  if (startIdx === -1) {
    warnings.push('INCIDENT REPORTS section not found.');
    return { drivers: [], warnings };
  }

  const section = text.slice(startIdx + 'INCIDENT REPORTS'.length);
  const drivers = [];
  const blockPattern =
    /(\d+)\s*-\s*([^:]+?)\s+CLASS:\s*([\s\S]*?)(?=\d+\s*-\s*[^:]+\s+CLASS:|$)/gi;

  let match;
  while ((match = blockPattern.exec(section)) !== null) {
    const carNumber = match[1].trim();
    const driverName = match[2].trim();
    const body = match[3] || '';

    const carMatch = body.match(/CAR:\s*(.+?)(?=\s+DRIVERS|\s+EVENTS|\s+LAPS|\s+PIT|$)/i);
    const car = carMatch ? carMatch[1].trim() : null;

    const driversMatch = body.match(/DRIVERS\s+(.+?)(?=\s+EVENTS|\s+LAPS|\s+PIT|$)/i);
    let iRating = null;
    let licenseClass = null;
    let safetyRating = null;

    if (driversMatch) {
      const parts = driversMatch[1].trim().split(/\s+/);
      for (const part of parts) {
        if (/^\d{3,5}$/.test(part)) iRating = Number(part);
        if (/^[A-Z]{1,3}$/.test(part)) licenseClass = part;
        if (/^\d+\.\d+$/.test(part)) safetyRating = Number(part);
      }
    }

    const eventsBlock = extractEventsBlock(body);
    const raceEventsText = extractRaceSection(eventsBlock, 'RACE');
    const pitStops = parseRacePitStops(raceEventsText);
    const incidentEvents = parseRaceIncidentEvents(raceEventsText);
    const bestLapEvents = parseRaceBestLapEvents(raceEventsText);

    const lapsBlock = body.match(/\bLAPS\b([\s\S]*)/i)?.[1] || '';
    const lapTableText = extractRaceSection(lapsBlock, 'RACE');
    const lapTableBest = parseLapTableBest(lapTableText);

    const resultRow = findMatchingResultRow(results, carNumber, driverName);
    const { bestLap, bestLapSource } = selectDriverBestLap({
      resultRow,
      bestLapEvents,
      lapTableBest,
    });
    const pitSummary = summarizePitStops(pitStops);
    const incidentCount =
      resultRow?.incidents != null && resultRow.incidents !== '-'
        ? Number(resultRow.incidents)
        : incidentEvents.length;

    drivers.push({
      carNumber,
      driverName,
      car,
      iRating,
      licenseClass,
      safetyRating,
      pitStops,
      pitStopCount: pitSummary.pitStopCount,
      fastestPitStop: pitSummary.fastestPitStop,
      totalPitStopTime: pitSummary.totalPitStopTime,
      bestLap,
      bestLapSource,
      incidentEvents,
      incidentCount: Number.isFinite(incidentCount) ? incidentCount : incidentEvents.length,
      raceEvents: incidentEvents.map((event) => event.text),
      resultIncidents: resultRow?.incidents ?? null,
    });
  }

  if (!drivers.length) {
    warnings.push('No driver incident reports detected.');
  }

  return { drivers, warnings };
}

function buildSummary(parsed, extraMeta = {}) {
  const results = parsed.results || [];
  const finishStatuses = new Set(['Running', 'Disco']);
  const finishers = results.filter((row) => finishStatuses.has(row.status)).length;

  let fastestLap = null;
  let fastestLapDriver = null;
  for (const row of results) {
    if (!row.bestLap || !isTimeToken(row.bestLap) || row.bestLap === '-') continue;
    if (!fastestLap || compareTimes(row.bestLap, fastestLap) < 0) {
      fastestLap = row.bestLap;
      fastestLapDriver = row.driverName;
    }
  }

  return {
    winner: parsed.winner || null,
    sof: parsed.sof ?? null,
    trackName: parsed.trackName || null,
    cautionCount: parsed.cautionCount ?? 0,
    totalDrivers: results.length,
    resultCount: results.length,
    finishers,
    dnfCount: Math.max(0, results.length - finishers),
    fastestLap,
    fastestLapDriver,
    ...extraMeta,
  };
}

function buildParserDiagnostics(sectionText, results, normalized, rowStarts) {
  const parsedRows = results.length;
  const expectedRows = rowStarts?.length ?? 0;
  let resultParseConfidence = 'low';
  if (parsedRows >= 30) resultParseConfidence = 'high';
  else if (parsedRows >= 10) resultParseConfidence = 'medium';

  return {
    resultsDetected: parsedRows,
    firstDriver: results[0]?.driverName || null,
    lastDriver: results[parsedRows - 1]?.driverName || null,
    expectedResultRows: expectedRows,
    parsedResultRows: parsedRows,
    resultParseConfidence,
    sectionAnchorsFound: {
      raceHeader: /This document was generated:/i.test(normalized),
      lapChart: /LAP CHART - RACE/i.test(normalized),
      sessionReports: /SESSION REPORTS/i.test(normalized),
      incidentReports: /INCIDENT REPORTS/i.test(normalized),
    },
  };
}

function addResultsSanityWarnings(parseWarnings, results, winner, sof) {
  if (results.length === 1 && winner) {
    parseWarnings.push(
      'Only the first finishing position was parsed. Results iteration failed.'
    );
  } else if (winner && results.length > 0 && results.length < 10) {
    parseWarnings.push(
      `Only ${results.length} finishing positions parsed. Results section likely terminated early.`
    );
  }

  if (sof != null && results.length > 0 && results.length < 10) {
    parseWarnings.push(
      'SOF detected but finishing order is incomplete. Parse is only partially healthy.'
    );
  }
}

export function buildRaceControlValidation(parsed, official = null) {
  if (!official) {
    return {
      winnerMatch: null,
      cautionMatch: null,
      sofMatch: null,
      warnings: ['No official comparison source available during parse.'],
    };
  }

  const warnings = [];
  const pdfWinner = parsed?.winner || parsed?.summary?.winner || null;
  const officialWinner = official?.winner || null;
  const pdfCautions = parsed?.cautionCount ?? parsed?.summary?.cautionCount ?? null;
  const officialCautions = official?.cautionCount ?? null;
  const pdfSof = parsed?.sof ?? parsed?.summary?.sof ?? null;
  const officialSof = official?.sof ?? null;

  let winnerMatch = null;
  if (pdfWinner && officialWinner) {
    winnerMatch = pdfWinner.toLowerCase() === officialWinner.toLowerCase();
    if (!winnerMatch) {
      warnings.push(
        `Race Control PDF winner (${pdfWinner}) differs from official winner (${officialWinner}). Official results take precedence.`
      );
    }
  }

  let cautionMatch = null;
  if (pdfCautions != null && officialCautions != null) {
    cautionMatch = pdfCautions === officialCautions;
    if (!cautionMatch) {
      warnings.push(
        `Race Control PDF caution count (${pdfCautions}) differs from official source (${officialCautions}).`
      );
    }
  }

  let sofMatch = null;
  if (pdfSof != null && officialSof != null) {
    sofMatch = pdfSof === officialSof;
    if (!sofMatch) {
      warnings.push(
        `Race Control PDF SOF (${pdfSof}) differs from official source (${officialSof}).`
      );
    }
  }

  return { winnerMatch, cautionMatch, sofMatch, warnings };
}

export async function extractPdfText(buffer) {
  if (!buffer?.length) {
    throw new Error('Empty PDF buffer.');
  }

  const pdf = await getDocumentProxy(new Uint8Array(buffer));
  const { text, totalPages } = await extractText(pdf, { mergePages: true });
  return {
    text: String(text || '').trim(),
    totalPages: Number(totalPages) || 0,
    extractionMethod: 'plain text',
  };
}

export function parseRaceControlPdfText(text, options = {}) {
  const normalized = normalizeWhitespace(text);
  const parseWarnings = [];
  const raceNumber = options.raceNumber != null ? Number(options.raceNumber) : null;
  const trackHint = options.trackName || null;

  if (!normalized) {
    return {
      raceNumber,
      generatedAt: null,
      trackName: trackHint,
      sof: null,
      winner: null,
      cautionCount: 0,
      results: [],
      raceEvents: [],
      drivers: [],
      summary: buildSummary({ results: [], winner: null, sof: null, trackName: trackHint, cautionCount: 0 }),
      parserDiagnostics: buildParserDiagnostics('', [], normalized, []),
      parseWarnings: ['PDF contained no extractable text.'],
    };
  }

  const header = parseRaceHeader(normalized);
  appendUniqueWarnings(parseWarnings, header.warnings);

  const resultsSection = getResultsSectionText(normalized);
  appendUniqueWarnings(parseWarnings, resultsSection.warnings);

  const parsedResults = parseResults(resultsSection.section);
  appendUniqueWarnings(parseWarnings, parsedResults.warnings);

  let parserDebug = null;
  if (options.collectParserDebug !== false) {
    try {
      const instrumentation = writeResultsParseInstrumentation(resultsSection.section);
      const failedRowDiagnostics = writeFailedRowDiagnostics(
        resultsSection.section,
        findResultRowCandidates(resultsSection.section)
      );
      parserDebug = {
        debugFilesWritten: instrumentation.debugFilesWritten,
        fullTextPath: options.fullTextPath || null,
        resultsSectionPath: instrumentation.resultsSectionPath,
        tokensPath: instrumentation.tokensPath,
        anchorsPath: instrumentation.anchorsPath,
        rowAttemptsPath: instrumentation.attemptsPath,
        failurePath: instrumentation.failurePath,
        failedRowsPath: failedRowDiagnostics.failedRowsPath,
        resultsSectionLength: instrumentation.resultsSectionLength,
        tokenCount: instrumentation.tokenCount,
        anchorCount: instrumentation.anchorCount,
        parsedAttemptCount: instrumentation.parsedAttemptCount,
        failedAtPosition: instrumentation.failedAtPosition,
        failureReason: instrumentation.failureReason,
        lastSuccessfulPosition: instrumentation.lastSuccessfulPosition,
        sequentialAnchorsAccepted: instrumentation.sequentialAnchorsAccepted,
        positionAnchorsDetected: instrumentation.positionAnchorsDetected,
        positions1Through35Detected: instrumentation.positions1Through35Detected,
        positions1Through35Count: instrumentation.positions1Through35Count,
        allPositions1Through35AnchorsDetected:
          instrumentation.allPositions1Through35AnchorsDetected,
        failedRowCount: failedRowDiagnostics.failedRowCount,
        failedPositions: failedRowDiagnostics.failedPositions,
        successfulPositions: failedRowDiagnostics.successfulPositions,
      };
    } catch (error) {
      parserDebug = {
        debugFilesWritten: false,
        instrumentationError: error?.message || String(error),
      };
    }
  }

  const session = parseSessionReports(normalized);
  appendUniqueWarnings(parseWarnings, session.warnings);

  const results = parsedResults.results;
  const driverReports = parseDriverReports(normalized, { results });
  appendUniqueWarnings(parseWarnings, driverReports.warnings);

  const cautionCount = session.raceEvents.filter((event) =>
    /FULL COURSE YELLOW/i.test(event.text)
  ).length;

  const winner = results[0]?.driverName || null;
  const trackName = header.trackName || trackHint || null;

  if (!trackName) parseWarnings.push('Track name not detected in PDF text.');
  if (header.sof == null) parseWarnings.push('SOF not detected in PDF text.');

  addResultsSanityWarnings(parseWarnings, results, winner, header.sof);

  const summaryMeta = extractRaceSummaryMeta(normalized, results);

  const parsed = {
    raceNumber,
    generatedAt: header.generatedAt,
    trackName,
    sof: header.sof,
    winner,
    cautionCount,
    results,
    raceEvents: session.raceEvents,
    drivers: driverReports.drivers,
    parseWarnings,
  };

  parsed.summary = buildSummary(parsed, summaryMeta);
  parsed.parserDiagnostics = buildParserDiagnostics(
    resultsSection.section,
    results,
    normalized,
    parsedResults.rowStarts
  );

  if (options.officialComparison) {
    parsed.validation = buildRaceControlValidation(parsed, options.officialComparison);
    appendUniqueWarnings(parseWarnings, parsed.validation.warnings);
  }

  if (parserDebug) {
    parsed.parserDebug = parserDebug;
  }

  return parsed;
}

export async function parseRaceControlPdfBuffer(buffer, options = {}) {
  const { text, totalPages } = await extractPdfText(buffer);
  const extractionMeta = buildExtractionDebug(text, totalPages);

  let fullTextPath = null;
  try {
    fullTextPath = writeParserDebugTextFile(PARSER_DEBUG_FILES.fullText, text);
  } catch {
    fullTextPath = null;
  }

  try {
    const debugFilePath = writeExtractionDebugFile(text);
    extractionMeta.debug.debugFileWritten = true;
    extractionMeta.debug.debugFilePath = debugFilePath;
  } catch {
    extractionMeta.debug.debugFileWritten = false;
  }

  const parsed = parseRaceControlPdfText(text, {
    ...options,
    fullTextPath,
    collectParserDebug: options.collectParserDebug !== false,
  });

  if (parsed.parserDebug) {
    parsed.parserDebug.fullTextPath = fullTextPath;
    parsed.parserDebug.debugFilesWritten = Boolean(fullTextPath && parsed.parserDebug.resultsSectionPath);
  }

  if (totalPages === 0) {
    parsed.parseWarnings.push('PDF parser returned zero pages.');
  }

  if (!parsed.results?.length && parsed.sof == null) {
    throw new Error('Insufficient iRaceControl data extracted: results empty and SOF missing.');
  }

  parsed.debugTextPreview = extractionMeta.debugTextPreview;
  parsed.debug = extractionMeta.debug;
  appendUniqueWarnings(parsed.parseWarnings, extractionMeta.extractionWarnings);

  return {
    parsedText: text,
    parsedJson: parsed,
    extractionSummary: {
      extractedCharacterCount: extractionMeta.debug.extractedCharacterCount,
      pageCount: extractionMeta.debug.pageCount,
      extractionMethod: extractionMeta.debug.extractionMethod,
      hasUsableText: extractionMeta.debug.hasUsableText,
      tablesLikelyFlattened: extractionMeta.debug.tablesLikelyFlattened,
      positionedTextLikely: extractionMeta.debug.positionedTextLikely,
      ocrLikelyRequired: extractionMeta.debug.ocrLikelyRequired,
      debugFileWritten: extractionMeta.debug.debugFileWritten,
      debugFilePath: extractionMeta.debug.debugFilePath,
    },
  };
}

export {
  buildExtractionDebug,
  resolveDebugFilePath,
  writeExtractionDebugFile,
  findSequentialResultRowStarts,
  resolveParserDebugPath,
  writeResultsParseInstrumentation,
  buildResultsParseInstrumentation,
  collectFailedRowDiagnostics,
  writeFailedRowDiagnostics,
};
